/* PRD 4, the economy's run-time side.
 *
 * Layer D, the definitive prices: def_item_prices (definitive_prices.c, generated by tools/gen_item_prices.py) holds the
 * items whose prices the rule changes, sorted by ID; the shops read every buying and selling price through
 * def_item_buy / def_item_sell (src/stitshop, under PC_PORT), so records_items itself is never patched and a price may
 * pass its u16. Layer E, the forge, below. Layer G: while a Legendary Replica of an ID is held, the ID resells for 0
 * (def_bm_resale_zero). Off in a replay script (def_on): the game's own prices, no recipe. */
#include "common.h"
#include "records.h"

#include "definitive.h"

extern int def_on(void); /* port.h declares it under PC_PORT only; the host test builds without it */
extern RecordsItem *records_get_item(s32 i);
extern void port_log(const char *fmt, ...);

static const DefItemPrice *price_of(int item) {
    int lo = 0, hi = def_item_price_count - 1;

    if (!def_on()) {
        return NULL;
    }
    while (lo <= hi) {
        int mid = (lo + hi) / 2;

        if (def_item_prices[mid].item == item) {
            return &def_item_prices[mid];
        }
        if (def_item_prices[mid].item < item) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return NULL;
}

int def_item_buy(int item) {
    const DefItemPrice *p = price_of(item);
    RecordsItem *rec;

    if (p != NULL) {
        return p->buy;
    }
    rec = records_get_item(item);
    return rec != NULL ? rec->price : 0;
}

int def_item_sell(int item) {
    const DefItemPrice *p = price_of(item);
    RecordsItem *rec;

    if (def_bm_resale_zero(item)) {
        return 0; /* the shop's sell list leaves out what pays 0, so the replica is not offered at all */
    }
    if (p != NULL) {
        return p->sell;
    }
    rec = records_get_item(item);
    return rec != NULL ? rec->sell_price : 0;
}

/* ---- Layer E, the forge: def_recipes (definitive_recipes.c, generated by tools/gen_recipes.py) lists the equipment
 * that asks for Hunt Materials besides its Bits, sorted by ID. The shop's buying screen (src/stitshop) refuses it as it
 * refuses a price it cannot pay, caps how many by what the materials make, takes them with the Bits, and shows the
 * requirements under the description, orange while short. */
extern const unsigned char def_str_RecipeSep[], def_str_RecipeMissing[], def_str_HuntSpace[], def_str_Slash[];

static const DefRecipe *recipe_of(int item) {
    int lo = 0, hi = def_recipe_count - 1;

    if (!def_on()) {
        return NULL;
    }
    while (lo <= hi) {
        int mid = (lo + hi) / 2;

        if (def_recipes[mid].item == item) {
            return &def_recipes[mid];
        }
        if (def_recipes[mid].item < item) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return NULL;
}

int def_recipe_max(int item) {
    const DefRecipe *r = recipe_of(item);
    int m, k;

    if (r == NULL) {
        return 99;
    }
    m = def_record_material(r->common) / r->common_n;
    if (r->rare >= 0) {
        k = def_record_rare(r->rare) / r->rare_n;
        m = k < m ? k : m;
    }
    return m;
}

int def_recipe_can_buy(int item) {
    return def_recipe_max(item) >= 1;
}

void def_recipe_pay(int item, int count) {
    const DefRecipe *r = recipe_of(item);

    if (r == NULL || count <= 0) {
        return;
    }
    def_record_material_add(r->common, -r->common_n * count);
    if (r->rare >= 0) {
        def_record_rare_add(r->rare, -r->rare_n * count);
    }
    port_log("forge: item %d x%d took material %d x%d, rare %d x%d", item, count, r->common, r->common_n * count, r->rare,
             r->rare_n * count);
}

/* "<common> 12/30" and, for a top item, ", <Rare Target> IV 0/1": the rare is named by the target that leaves it, which
 * is shorter than its item's name and fits the line. */
const unsigned char *def_recipe_label(int item, int *palette) {
    static unsigned char buf[DEF_HUNT_LINE_SIZE + 40];
    const DefRecipe *r = recipe_of(item);
    int p = 0;

    if (r == NULL) {
        return NULL;
    }
    buf[0] = 0;
    def_glyph_put(buf, &p, sizeof(buf), def_hunt_material_name(r->common));
    def_glyph_put(buf, &p, sizeof(buf), def_str_HuntSpace);
    def_glyph_count(buf, &p, sizeof(buf), def_record_material(r->common));
    def_glyph_put(buf, &p, sizeof(buf), def_str_Slash);
    def_glyph_count(buf, &p, sizeof(buf), r->common_n);
    if (r->rare >= 0) {
        def_glyph_put(buf, &p, sizeof(buf), def_str_RecipeSep);
        def_hunt_target_name(buf, &p, sizeof(buf), r->rare);
        def_glyph_put(buf, &p, sizeof(buf), def_str_HuntSpace);
        def_glyph_count(buf, &p, sizeof(buf), def_record_rare(r->rare));
        def_glyph_put(buf, &p, sizeof(buf), def_str_Slash);
        def_glyph_count(buf, &p, sizeof(buf), r->rare_n);
    }
    if (palette != NULL) {
        *palette = def_recipe_can_buy(item) ? 0 : 3;
    }
    return buf;
}

const unsigned char *def_recipe_missing_text(void) {
    return def_str_RecipeMissing;
}
